it('weekYear matches moment for every day 2010-2025', () => {
  let total = 0
  locales.forEach((name) => {
    dayjs.locale(name)
    moment.locale(name)
    let count = 0
    const start = new Date(Date.UTC(2010, 0, 1))
    const end = new Date(Date.UTC(2025, 11, 31))
    for (let d = new Date(start); d <= end; d.setUTCDate(d.getUTCDate() + 1)) {
