      const mo = moment(date).weekYear()
      if (dj !== mo) {
        count += 1
        console.log(`${name} | ${date} | dayjs=${dj} | moment=${mo}`)
      }
    }
    console.log(`locale ${name}: ${count} mismatches`)
    total += count
  })
  console.log(`TOTAL mismatches: ${total}`)
})

